// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  AbsoluteFill,
  interpolate,
  interpolateColors,
  spring,
  useCurrentFrame,
  useVideoConfig,
  Easing,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadRoboto = makeLoadFont('Roboto');

// Load Roboto font at module level to prevent flickering
const { fontFamily: robotoFamily } = loadRoboto();



export type YoutubeSubscribeProps = Record<string, any>;

const YoutubeSubscribe: React.FC<YoutubeSubscribeProps> = ({
  backgroundColor = "#F2F2F2",
  transparentBackground = false,
  durationInSeconds = 5,
  buttonColor = "#C5302E",
  subscribedColor = "#606060",
  textColor = "#FFFFFF",
  buttonText = "Subscribe",
  subscribedText = "Subscribed",
  cursorColor = "#FFFFFF",
  cursorStrokeColor = "#000000",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Background Logic
  const bgStyleColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Timeline Markers
  const introEnd = 10;
  const cursorMoveStart = 30;
  const cursorMoveEnd = 60;
  const clickStart = 75;
  const clickEnd = 80;
  const stateEnd = 85;

  // Responsive Exit Timeline
  const totalFrames = Math.round(durationInSeconds * fps);
  const leaveStart = Math.max(100, totalFrames - 50);
  const leaveEnd = Math.max(130, totalFrames - 20);

  // Animations
  const buttonEntrance = spring({
    fps,
    frame: frame - introEnd,
    config: { damping: 12, stiffness: 100 },
  });

  const clickPress = interpolate(frame, [clickStart, clickEnd, stateEnd], [1, 0.94, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  
  const buttonScale = buttonEntrance * clickPress;

  const buttonBgColor = interpolateColors(
    frame,
    [clickEnd, stateEnd],
    [buttonColor, subscribedColor]
  );

  const unsubOpacity = interpolate(frame, [clickEnd, stateEnd], [1, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  
  const subOpacity = interpolate(frame, [clickEnd, stateEnd], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Cursor Movement
  const startX = width + 200;
  const startY = height + 200;
  const targetX = width / 2 + 20;
  const targetY = height / 2 + 20;

  const cursorX = interpolate(
    frame,
    [cursorMoveStart, cursorMoveEnd, leaveStart, leaveEnd],
    [startX, targetX, targetX, startX],
    { easing: Easing.inOut(Easing.quad), extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  const cursorY = interpolate(
    frame,
    [cursorMoveStart, cursorMoveEnd, leaveStart, leaveEnd],
    [startY, targetY, targetY, startY],
    { easing: Easing.inOut(Easing.quad), extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  const cursorClickScale = interpolate(
    frame,
    [clickStart, clickEnd, stateEnd],
    [1, 0.85, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  return (
    <AbsoluteFill style={{ backgroundColor: bgStyleColor, overflow: "hidden" }}>
      
      {/* Button Container */}
      <AbsoluteFill style={{ alignItems: "center", justifyContent: "center" }}>
        <div
          style={{
            width: 420,
            height: 96,
            backgroundColor: buttonBgColor,
            borderRadius: 12,
            boxShadow: "0px 15px 45px rgba(0,0,0,0.15)",
            position: "relative",
            transform: `scale(${buttonScale})`,
            transition: "none",
          }}
        >
          {/* Unsubscribed State */}
          <div
            style={{
              position: "absolute",
              left: 0,
              top: 0,
              right: 0,
              bottom: 0,
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              opacity: unsubOpacity,
              transition: "none",
            }}
          >
            <svg width="60" height="45" viewBox="0 0 60 45" fill="none">
              <rect width="60" height="45" rx="10" fill="white" />
              <path d="M 24 15 L 24 30 L 39 22.5 Z" fill={buttonColor} />
            </svg>
            <span
              style={{
                color: textColor,
                fontWeight: 700,
                fontSize: 40,
                marginLeft: 20,
                fontFamily: robotoFamily,
              }}
            >
              {buttonText}
            </span>
          </div>

          {/* Subscribed State */}
          <div
            style={{
              position: "absolute",
              left: 0,
              top: 0,
              right: 0,
              bottom: 0,
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              opacity: subOpacity,
              transition: "none",
            }}
          >
            <span
              style={{
                color: textColor,
                fontWeight: 700,
                fontSize: 40,
                fontFamily: robotoFamily,
              }}
            >
              {subscribedText}
            </span>
          </div>
        </div>
      </AbsoluteFill>

      {/* Mouse Cursor */}
      <AbsoluteFill>
        <div
          style={{
            position: "absolute",
            left: cursorX,
            top: cursorY,
            transform: `scale(${cursorClickScale})`,
            transformOrigin: "0 0",
            zIndex: 10,
            filter: "drop-shadow(4px 8px 12px rgba(0,0,0,0.3))",
            transition: "none",
          }}
        >
          <svg width="64" height="64" viewBox="0 0 64 64" fill="none">
            <path
              d="M0 0 L0 48 L14 34 L24 54 L32 50 L22 30 L40 30 Z"
              fill={cursorColor}
              stroke={cursorStrokeColor}
              strokeWidth="3"
              strokeLinejoin="round"
            />
          </svg>
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

export default YoutubeSubscribe;